82: static Py_ssize_t cdl_4bytes(char *src)
83: {
84:     /* read 4 bytes in big-endian order; return it as a signed integer */
85:     signed char *ssrc = (signed char *)src;
86:     unsigned char *usrc = (unsigned char *)src;
87:     return (ssrc[0] << 24) | (usrc[1] << 16) | (usrc[2] << 8) | usrc[3];
88: }
89: 
90: static _cffi_opcode_t cdl_opcode(char *src)
91: {
92:     return (_cffi_opcode_t)cdl_4bytes(src);
93: }
