116: static int ffiobj_init(PyObject *self, PyObject *args, PyObject *kwds)
117: {
118:     FFIObject *ffi;
119:     static char *keywords[] = {"module_name", "_version", "_types",
120:                                "_globals", "_struct_unions", "_enums",
121:                                "_typenames", "_includes", NULL};
122:     char *ffiname = "?", *types = NULL, *building = NULL;
123:     Py_ssize_t version = -1;
124:     Py_ssize_t types_len = 0;
125:     PyObject *globals = NULL, *struct_unions = NULL, *enums = NULL;
126:     PyObject *typenames = NULL, *includes = NULL;
127: 
128:     if (!PyArg_ParseTupleAndKeywords(args, kwds,
129:                                      "|sns#O!O!O!O!O!:FFI", keywords,
130:                                      &ffiname, &version, &types, &types_len,
131:                                      &PyTuple_Type, &globals,
132:                                      &PyTuple_Type, &struct_unions,
133:                                      &PyTuple_Type, &enums,
134:                                      &PyTuple_Type, &typenames,
135:                                      &PyTuple_Type, &includes))
136:         return -1;
137: 
138:     ffi = (FFIObject *)self;
139:     if (ffi->ctx_is_nonempty) {
140:         PyErr_SetString(PyExc_ValueError,
141:                         "cannot call FFI.__init__() more than once");
142:         return -1;
143:     }
144:     ffi->ctx_is_nonempty = 1;
145: 
146:     if (version == -1 && types_len == 0)
147:         return 0;
148:     if (version < CFFI_VERSION_MIN || version > CFFI_VERSION_MAX) {
149:         PyErr_Format(PyExc_ImportError,
150:                      "cffi out-of-line Python module '%s' has unknown "
151:                      "version %p", ffiname, (void *)version);
152:         return -1;
153:     }
154: 
155:     if (types_len > 0) {
156:         /* unpack a string of 4-byte entries into an array of _cffi_opcode_t */
157:         _cffi_opcode_t *ntypes;
158:         Py_ssize_t i, n = types_len / 4;
159: 
160:         building = PyMem_Malloc(n * sizeof(_cffi_opcode_t));
161:         if (building == NULL)
162:             goto error;
163:         ntypes = (_cffi_opcode_t *)building;
164: 
165:         for (i = 0; i < n; i++) {
166:             ntypes[i] = cdl_opcode(types);
167:             types += 4;
168:         }
169:         ffi->types_builder.ctx.types = ntypes;
170:         ffi->types_builder.ctx.num_types = n;
171:         building = NULL;
172:     }
173: 
174:     if (globals != NULL) {
175:         /* unpack a tuple alternating strings and ints, each two together
176:            describing one global_s entry with no specified address or size.
177:            The int is only used with integer constants. */
178:         struct _cffi_global_s *nglobs;
179:         cdl_intconst_t *nintconsts;
180:         Py_ssize_t i, n = PyTuple_GET_SIZE(globals) / 2;
181: 
182:         i = n * (sizeof(struct _cffi_global_s) + sizeof(cdl_intconst_t));
183:         building = PyMem_Malloc(i);
184:         if (building == NULL)
185:             goto error;
186:         memset(building, 0, i);
187:         nglobs = (struct _cffi_global_s *)building;
188:         nintconsts = (cdl_intconst_t *)(nglobs + n);
189: 
190:         for (i = 0; i < n; i++) {
191:             char *g = PyBytes_AS_STRING(PyTuple_GET_ITEM(globals, i * 2));
192:             nglobs[i].type_op = cdl_opcode(g); g += 4;
193:             nglobs[i].name = g;
194:             if (_CFFI_GETOP(nglobs[i].type_op) == _CFFI_OP_CONSTANT_INT ||
195:                 _CFFI_GETOP(nglobs[i].type_op) == _CFFI_OP_ENUM) {
196:                 PyObject *o = PyTuple_GET_ITEM(globals, i * 2 + 1);
197:                 nglobs[i].address = &_cdl_realize_global_int;
198:                 {
199:                     nintconsts[i].neg = PyObject_RichCompareBool(o, Py_False,
200:                                                                  Py_LE);
201:                     nintconsts[i].value = PyLong_AsUnsignedLongLongMask(o);
202:                     if (PyErr_Occurred())
203:                         goto error;
204:                 }
205:             }
206:         }
207:         ffi->types_builder.ctx.globals = nglobs;
208:         ffi->types_builder.ctx.num_globals = n;
209:         building = NULL;
210:     }
211: 
212:     if (struct_unions != NULL) {
213:         /* unpack a tuple of struct/unions, each described as a sub-tuple;
214:            the item 0 of each sub-tuple describes the struct/union, and
215:            the items 1..N-1 describe the fields, if any */
216:         struct _cffi_struct_union_s *nstructs;
217:         struct _cffi_field_s *nfields;
218:         Py_ssize_t i, n = PyTuple_GET_SIZE(struct_unions);
219:         Py_ssize_t nf = 0;   /* total number of fields */
220: 
221:         for (i = 0; i < n; i++) {
222:             nf += PyTuple_GET_SIZE(PyTuple_GET_ITEM(struct_unions, i)) - 1;
223:         }
224:         i = (n * sizeof(struct _cffi_struct_union_s) +
225:              nf * sizeof(struct _cffi_field_s));
226:         building = PyMem_Malloc(i);
227:         if (building == NULL)
228:             goto error;
229:         memset(building, 0, i);
230:         nstructs = (struct _cffi_struct_union_s *)building;
231:         nfields = (struct _cffi_field_s *)(nstructs + n);
232:         nf = 0;
233: 
234:         for (i = 0; i < n; i++) {
235:             /* 'desc' is the tuple of strings (desc_struct, desc_field_1, ..) */
236:             PyObject *desc = PyTuple_GET_ITEM(struct_unions, i);
237:             Py_ssize_t j, nf1 = PyTuple_GET_SIZE(desc) - 1;
238:             char *s = PyBytes_AS_STRING(PyTuple_GET_ITEM(desc, 0));
239:             /* 's' is the first string, describing the struct/union */
240:             nstructs[i].type_index = cdl_4bytes(s); s += 4;
241:             nstructs[i].flags = cdl_4bytes(s); s += 4;
242:             nstructs[i].name = s;
243:             if (nstructs[i].flags & (_CFFI_F_OPAQUE | _CFFI_F_EXTERNAL)) {
244:                 nstructs[i].size = (size_t)-1;
245:                 nstructs[i].alignment = -1;
246:                 nstructs[i].first_field_index = -1;
247:                 nstructs[i].num_fields = 0;
248:                 assert(nf1 == 0);
249:             }
250:             else {
251:                 nstructs[i].size = (size_t)-2;
252:                 nstructs[i].alignment = -2;
253:                 nstructs[i].first_field_index = nf;
254:                 nstructs[i].num_fields = nf1;
255:             }
256:             for (j = 0; j < nf1; j++) {
257:                 char *f = PyBytes_AS_STRING(PyTuple_GET_ITEM(desc, j + 1));
258:                 /* 'f' is one of the other strings beyond the first one,
259:                    describing one field each */
260:                 nfields[nf].field_type_op = cdl_opcode(f); f += 4;
261:                 nfields[nf].field_offset = (size_t)-1;
262:                 if (_CFFI_GETOP(nfields[nf].field_type_op) != _CFFI_OP_NOOP) {
263:                     nfields[nf].field_size = cdl_4bytes(f); f += 4;
264:                 }
